//! Startup gate: initialize the browser database or verify the remote server
//! before the app mounts any data-backed screen.

use crate::domain::health::API_VERSION;
use wasm_bindgen_futures::JsFuture;

/// Stable path generated by the root build script.
const SEED_PATH: &str = "/btc_usd.bin";

fn seed_url() -> String {
    let origin = web_sys::window()
        .and_then(|window| window.location().origin().ok())
        .unwrap_or_default();
    format!("{origin}{SEED_PATH}")
}

pub async fn boot() -> Result<(), String> {
    if crate::backend::is_remote() {
        let health = crate::api::remote::health_at_current()
            .await
            .map_err(|error| format!("Could not connect to the remote backend: {error}"))?;
        if health.api_version != API_VERSION {
            return Err(format!(
                "API version mismatch: this app uses API {API_VERSION}, the server uses API {}. Choose a compatible server or use the local database.",
                health.api_version
            ));
        }
        Ok(())
    } else {
        request_persistent_storage().await;
        if !local_worker_available().await {
            return Err(
                "The SharedWorker script is missing from this deployment. Rebuild the web app with `dx serve` or `dx build --web`."
                    .to_string(),
            );
        }
        crate::web::worker::init(&seed_url())
            .await
            .map(|_| ())
            .map_err(|error| format!("Could not prepare the browser-local database: {error}"))
    }
}

/// Best-effort request for persistent origin storage. Denial or lack of
/// support must not block the browser-local database.
async fn request_persistent_storage() {
    let Some(storage) = web_sys::window().map(|window| window.navigator().storage()) else {
        return;
    };
    let Ok(promise) = storage.persist() else {
        return;
    };
    let _ = JsFuture::from(promise).await;
}

async fn local_worker_available() -> bool {
    let Some(window) = web_sys::window() else {
        return false;
    };
    let Ok(origin) = window.location().origin() else {
        return false;
    };
    let Ok(response) = reqwest::get(format!("{origin}/local-worker.js")).await else {
        return false;
    };
    if !response.status().is_success() {
        return false;
    }
    let is_html = response
        .headers()
        .get(reqwest::header::CONTENT_TYPE)
        .and_then(|value| value.to_str().ok())
        .map(|value| value.contains("text/html"))
        .unwrap_or(false);
    if is_html {
        return false;
    }
    response
        .bytes()
        .await
        .map(|bytes| !bytes.starts_with(b"<!DOCTYPE") && !bytes.starts_with(b"<html"))
        .unwrap_or(false)
}
